module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // re.compile with user input
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("compile").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.search with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("search").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.match with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("match").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.findall with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("findall").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.finditer with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("finditer").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.sub with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("sub").getACall() and
      sink = call.getArg(0)
    )
    or
    // re.split with user input as pattern
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember("split").getACall() and
      sink = call.getArg(0)
    )
  }
}

